import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s6-u14")
C = "B1-B2"
# Lições de aprofundamento (10–25): colocações.

def X(id, nl, pt, pos="expression"): return V(id, nl, pt, pos)

L(10, "Colocações com nemen (1)", "Neem de tijd!",
  ["Usar nemen em colocações frequentes"],
  vocab=[X("v-de-tijd-nemen","de tijd nemen","não ter pressa|tirar tempo"), X("v-risico-nemen","een risico nemen","correr um risco"),
         X("v-in-gebruik-nemen","in gebruik nemen","pôr em funcionamento")],
  ex=[("Neem rustig de tijd.","Não tenhas pressa."),("Ik wil geen onnodig risico nemen.","Não quero correr riscos desnecessários."),("Het nieuwe station wordt in maart in gebruik genomen.","A nova estação entra em funcionamento em março.")],
  review=["v-besluit-nemen","v-afscheid-nemen"],
  cefr=C, exs=[
    MA([("de tijd nemen","não ter pressa"),("een risico nemen","correr um risco"),("in gebruik nemen","pôr em funcionamento"),("een besluit nemen","tomar uma decisão")], "Nemen.", ["v-de-tijd-nemen","v-risico-nemen","v-in-gebruik-nemen","v-besluit-nemen"]),
    MC("Em PT «corre-se» um risco. Em NL…", ["*neem je een risico","loop je een risico|Também existe, mas «nemen» = assumir.","maak je een risico|Não."], "Colocação.", ["v-risico-nemen"]),
    TR("pt-nl","Não tenhas pressa.", ["Neem rustig de tijd","Neem de tijd","Neem je tijd"], "Expressão.", ["v-de-tijd-nemen"]),
    TR("pt-nl","A nova estação entra em funcionamento em março.", ["Het nieuwe station wordt in maart in gebruik genomen"], "in gebruik nemen.", ["v-in-gebruik-nemen"]),
    FB("Ik wil geen onnodig risico ___.", ["nemen"], "Colocação.", ["v-risico-nemen"], choices=["nemen","maken","doen"], tr="Não quero correr riscos desnecessários."),
    FE(["Hij","maakt","een","groot","risico."], 1, "neemt", "Colocação: een risico nemen.", ["v-risico-nemen"]),
    LI("Neem gerust de tijd om het contract te lezen.", ["Neem gerust de tijd om het contract te lezen"], "Tire o tempo que quiser para ler o contrato.", "Uso.", ["v-de-tijd-nemen"]),
    DL([("Klant","Moet ik nu meteen beslissen?","Tenho de decidir já?"),("Jij (verkoper)","","")], ["*Nee hoor, neem rustig de tijd en laat het me volgende week weten.","Ja, nu!|Pressão.","Risico nemen.|Sem sentido."], "Sem pressão.", ["v-de-tijd-nemen"]),
    WO("Não tenhas pressa.", ["Neem","rustig","de","tijd"], "Ordem.", ["v-de-tijd-nemen"]),
  ], diff=4, mins=5)

